{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.installments import installments"
  ],
  "tests": [
    {
      "name": "test_installments_last_absorbs_remainder",
      "intent": "the bug example from the task: 100.00 into 3 instalments",
      "code": "# intent: the bug example from the task: 100.00 into 3 instalments\ndef test_installments_last_absorbs_remainder():\n    assert installments(Decimal(\"100.00\"), 3) == [Decimal(\"33.33\"), Decimal(\"33.33\"), Decimal(\"33.34\")]\n"
    },
    {
      "name": "test_installments_evenly_divisible",
      "intent": "evenly divisible total returns equal instalments",
      "code": "# intent: evenly divisible total returns equal instalments\ndef test_installments_evenly_divisible():\n    assert installments(Decimal(\"90.00\"), 3) == [Decimal(\"30.00\")] * 3\n"
    },
    {
      "name": "test_installments_single_payment",
      "intent": "single instalment returns the total",
      "code": "# intent: single instalment returns the total\ndef test_installments_single_payment():\n    assert installments(Decimal(\"50.00\"), 1) == [Decimal(\"50.00\")]\n"
    },
    {
      "name": "test_installments_zero_count_raises",
      "intent": "zero count is invalid and raises ValueError",
      "code": "# intent: zero count is invalid and raises ValueError\ndef test_installments_zero_count_raises():\n    with pytest.raises(ValueError):\n        installments(Decimal(\"50.00\"), 0)\n"
    },
    {
      "name": "test_installments_negative_count_raises",
      "intent": "negative count is invalid and raises ValueError",
      "code": "# intent: negative count is invalid and raises ValueError\ndef test_installments_negative_count_raises():\n    with pytest.raises(ValueError):\n        installments(Decimal(\"50.00\"), -1)\n"
    },
    {
      "name": "test_installments_rounding_down_keeps_cents",
      "intent": "instalments are rounded down to cents, last absorbs remainder",
      "code": "# intent: instalments are rounded down to cents, last absorbs remainder\ndef test_installments_rounding_down_keeps_cents():\n    assert installments(Decimal(\"0.05\"), 2) == [Decimal(\"0.02\"), Decimal(\"0.03\")]\n"
    }
  ]
}
